// ============================================================================
// 领域切分策略（api-docs）：API 文档代码示例密集，通用 450 字窗口常把代码块拦腰截断
// ----------------------------------------------------------------------------
// 策略：复用内核 chunkText（标题分段 + 贪心打包 + 滑窗），仅调参——
//   maxChars 450 → 900：整段接口说明+代码示例尽量同块，保证"参数表+示例"不被拆散；
//   overlap 60 → 100：滑窗切断时重叠加宽，代码片段前后文连续性更好。
// 诚实标注：这是参数化策略而非新算法；若后续需要"按代码围栏切"，再独立实现。
// ============================================================================

import { chunkText } from '../../rag/chunker.js'

export function chunkApiDoc(text) {
  return chunkText(text, { maxChars: 900, overlap: 100 })
}
